module Math {
    fun fibonacci(n: i32): i32 {
        if (n <= 1) {
            return n
        }

        let mut a: i32 = 0
        let mut b: i32 = 1
        let mut i: i32 = 2

        while (i <= n) {
            let temp: i32 = a + b
            a = b
            b = temp
            i = i + 1
        }

        return b
    }
}

module Algorithms {
    fun binarySearch(arr: []i32, target: i32): i32 {
        let mut low: i32 = 0
        let mut high: i32 = arr.length - 1

        while (low <= high) {
            let mid: i32 = low + (high - low) / 2

            if (arr[mid] == target) {
                return mid  // Found the target
            }

            if (arr[mid] < target) {
                low = mid + 1
            } else {
                high = mid - 1
            }
        }

        return -1  // Target not found
    }
}
